          </Title>
          <List
            spacing="md"
            center={false}
            icon={
              <ThemeIcon size={24} radius="xl" variant="light">
                <IconCircleDashed size={16} aria-hidden="true" />
              </ThemeIcon>
            }
          >
            {checklist.map((item) => (
              <List.Item key={item.title}>
                <Box>
                  <Text fw={600}>{item.title}</Text>
                  <Text size="sm" c="dimmed">
                    {item.text}
                  </Text>
                </Box>
              </List.Item>
            ))}
          </List>
        </Card>

        <Group>
          <Button component={Link} href="/">
            Back to onboarding
          </Button>
        </Group>
      </Stack>
    </Container>
  );
}
